// OutLayer entry: JSON in on stdin, `{ success, output, error }` out on stdout. The secret `PROTECTED_BRAIN_SEED` is
// generated by OutLayer inside the TEE and reaches the module as an environment variable; it never leaves. For a plan
// the module first checks the run's signer (`NEAR_SENDER_ID`, over HTTPS the payment key's owner) against the keeper,
// then reads the factory through the worker's own RPC and asks NEAR AI Cloud over HTTPS with the project's secret
// `NEAR_AI_API_KEY`, both from inside the TEE.
//
// The module carries its own manifest (`manifest.json`) in the wasm section OutLayer reads, `outlayer.manifest`, under
// the same sha256 as the code. It says two things: the module reaches cloud-api.near.ai over HTTPS and no other host,
// and one request there may take `MODEL_SECONDS`, in place of the 30 seconds OutLayer gives a request otherwise. The
// models think for minutes on the live safe, so without it no answer would ever come back.

/// `#[used]` keeps the linker from dropping a static nothing reads.
#[cfg(target_os = "wasi")]
#[used]
#[link_section = "outlayer.manifest"]
static OUTLAYER_MANIFEST: [u8; include_bytes!("../manifest.json").len()] =
    *include_bytes!("../manifest.json");

#[cfg(target_os = "wasi")]
mod world {
    use maskwars_brain::http::post;
    use maskwars_brain::mind::{
        out_of_time, out_of_time_words, Chain, Llm, Reply, Usage, CONNECT_SECONDS, NO_KEY,
    };
    use serde_json::{json, Value};
    use std::time::{Duration, Instant};

    /// The NEAR RPC that the OutLayer worker itself gives the module (`near:rpc`), for the network it serves.
    pub struct WorkerRpc;

    impl Chain for WorkerRpc {
        fn rpc(&self, method: &str, params: Value) -> Result<Value, String> {
            let (body, error) = outlayer::raw::rpc::raw(method, &params.to_string());
            if !error.is_empty() {
                return Err("the worker's RPC is unreachable".into());
            }
            serde_json::from_str(&body).map_err(|_| "the RPC's answer is not JSON".to_string())
        }
    }

    /// NEAR AI Cloud's chat completions: canonical model ids, no aliasing, no streaming.
    pub struct NearAi {
        pub key: String,
    }

    impl Llm for NearAi {
        fn complete(
            &self,
            model: &str,
            messages: &[Value],
            max_tokens: u32,
            temperature: f32,
        ) -> Result<Reply, String> {
            // A project with no key of its own: the header would be `Bearer ` alone, which wasi-http refuses with a
            // trap. Say so instead, before anything is sent.
            if self.key.trim().is_empty() {
                return Err(NO_KEY.to_string());
            }
            let body = json!({ "model": model, "messages": messages, "stream": false, "max_tokens": max_tokens,
                               "temperature": temperature });
            // The answer is not streamed, so nothing comes back until the model is done. OutLayer ends the request
            // after the time the manifest names for this host (`MODEL_SECONDS`), or sooner when the run has less
            // left; the run itself goes on, and the module says what happened, with the seconds the model was given,
            // instead of running into the run's own limit.
            let asked = Instant::now();
            // The body goes out in pieces of 4096 bytes (src/http.rs): one write takes no more, and the request
            // carries the target's source.
            let (status, body) = post(
                true,
                "cloud-api.near.ai",
                "/v1/chat/completions",
                &[
                    ("content-type", "application/json"),
                    ("accept", "application/json"),
                    ("authorization", &format!("Bearer {}", self.key.trim())),
                    ("x-no-aliasing", "true"),
                    ("user-agent", "maskwars-brain"),
                ],
                body.to_string().as_bytes(),
                Duration::from_secs(CONNECT_SECONDS),
            )
            .map_err(|e| {
                let waited = asked.elapsed().as_secs();
                if out_of_time(&e, waited) {
                    out_of_time_words(waited)
                } else if e.starts_with("the answer") {
                    "NEAR AI's answer was cut".to_string()
                } else {
                    "NEAR AI is unreachable".to_string()
                }
            })?;
            if status != 200 {
                return Err(format!("NEAR AI answered {status}"));
            }
            let v: Value = serde_json::from_slice(&body)
                .map_err(|_| "NEAR AI's answer is not JSON".to_string())?;
            // A model that thinks until its allowance runs out answers with no content and `finish_reason: length`.
            let text = v["choices"][0]["message"]["content"]
                .as_str()
                .map(str::to_string);
            let cut = v["choices"][0]["finish_reason"] == "length";
            let usage = Usage {
                prompt_tokens: v["usage"]["prompt_tokens"].as_u64().unwrap_or(0),
                completion_tokens: v["usage"]["completion_tokens"].as_u64().unwrap_or(0),
                cached_tokens: v["usage"]["prompt_tokens_details"]["cached_tokens"]
                    .as_u64()
                    .unwrap_or(0),
            };
            Ok(Reply {
                text,
                cut,
                model: v["model"].as_str().unwrap_or_default().to_string(),
                usage,
            })
        }
    }
}

#[cfg(target_os = "wasi")]
fn main() {
    use maskwars_brain::{handle, Input, Output};
    use outlayer::env;

    let seed = std::env::var("PROTECTED_BRAIN_SEED")
        .ok()
        .filter(|s| !s.is_empty());
    let llm = world::NearAi {
        key: std::env::var("NEAR_AI_API_KEY").unwrap_or_default(),
    };
    let out = match env::input_json::<Input>() {
        Ok(Some(input)) => {
            let caller = env::signer_account_id().filter(|s| !s.is_empty());
            handle(
                input,
                seed.as_deref(),
                caller.as_deref(),
                &world::WorkerRpc,
                &llm,
            )
        }
        _ => Output {
            success: false,
            output: serde_json::Value::Null,
            error: Some("bad input".into()),
        },
    };
    let _ = env::output_json(&out);
}

#[cfg(not(target_os = "wasi"))]
fn main() {
    eprintln!("maskwars-brain runs on OutLayer: build with --target wasm32-wasip2");
    std::process::exit(1);
}
